                else {
                    long *bytes_of_page = (long *)prepare_page_for_va((uintptr_t)(phdr->p_vaddr + i), pgdir);
                    for (int j = 0; j < NORMAL_PAGE_SIZE / sizeof(long); ++j) {
                        bytes_of_page[j] = 0;
                    }
                }
            }
        }

        ptr_ph_table += ph_entry_size;
    }

